-- Check the total number of robots and operations to understand "running over a while"
SELECT COUNT(DISTINCT upkeeprobot) as total_robots FROM maintenance_and_fault;
SELECT COUNT(*) FROM operation;

-- Check what "TOH" might mean - total operating hours from operation table
-- Let's also check how many operations each robot has via the operation table directly
SELECT operbotdetref, COUNT(*) as op_count FROM operation GROUP BY operbotdetref ORDER BY op_count DESC LIMIT 10;

-- Let me check the robot_record table to understand the relationship better
SELECT COUNT(*) FROM robot_record;
SELECT COUNT(*) FROM operation;
SELECT COUNT(*) FROM maintenance_and_fault;

-- Let me check if there's a different way to interpret "Number of Operations"
-- Maybe it refers to total operations across all records, not just per robot
SELECT COUNT(*) FROM operation;

-- Let me check how many distinct botcodes there are vs recregs
SELECT COUNT(DISTINCT botcode) FROM robot_record;
SELECT COUNT(*) FROM robot_record;

-- 1000 distinct botcodes and 1000 records - so each botcode has exactly one record on average
-- But some have 2. Let me check the distribution
SELECT COUNT(*) FROM (SELECT botcode, COUNT(*) as cnt FROM robot_record GROUP BY botcode HAVING COUNT(*) > 1) sub;

-- Let me check the robot_details table - maybe it has one record per botcode
SELECT COUNT(*) FROM robot_details;
SELECT COUNT(DISTINCT botdetreg) FROM robot_details;
